def appartient(x, a, b, ouvert_gauche, ouvert_droit):
    if ouvert_gauche:
        if not (x > a):
            return False
    else:
        if not (x >= a):
            return False
    if ouvert_droit:
        if not (x < b):
            return False
    else:
        if not (x <= b):
            return False
    return True
